arguments.new_str:
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);

// Register the model training service and train eagerly
var trainService = new TicketModelService(
    LoggerFactory.Create(b => b.AddConsole()).CreateLogger<TicketModelService>(),
    builder.Environment);
trainService.TrainAndSave();
builder.Services.AddSingleton(trainService);

// Register the pooled prediction engine (thread-safe for ASP.NET Core)
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();

app.MapPost("/api/ticket/classify", (
    TicketRequest request,
    PredictionEnginePool<TicketInput, TicketPrediction> predictionPool) =>
{
    if (string.IsNullOrWhiteSpace(request.Subject) || string.IsNullOrWhiteSpace(request.Description))
        return Results.BadRequest("Subject and Description are required.");

    if (request.Priority < 1 || request.Priority > 3)
        return Results.BadRequest("Priority must be between 1 and 3.");

    var input = new TicketInput
    {
        Subject = request.Subject,
        Description = request.Description,
        Priority = request.Priority
    };

    var prediction = predictionPool.Predict(input);

    var categories = new[] { "Billing", "General", "Technical" };
    var confidence = new Dictionary<string, float>();
    for (int i = 0; i < categories.Length && i < prediction.Score.Length; i++)
        confidence[categories[i]] = prediction.Score[i];

    return Results.Ok(new PredictionResponse
    {
        PredictedCategory = prediction.Category,
        Confidence = confidence
    });
});

app.MapGet("/api/ticket/metrics", (TicketModelService modelService) =>
{
    if (modelService.LastMetrics is null)
        return Results.NotFound("Model has not been trained yet.");

    return Results.Ok(modelService.LastMetrics);
});

app.MapPost("/api/ticket/retrain", (TicketModelService modelService) =>
{
    modelService.TrainAndSave();
    return Results.Ok(modelService.LastMetrics);
});

app.Run();

