toolArgs.old_str:
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();

// Register the model training service as singleton so metrics persist
builder.Services.AddSingleton<TicketModelService>();

// Train the model eagerly so the .zip file exists for the prediction pool
var tempLogger = LoggerFactory.Create(b => b.AddConsole()).CreateLogger<TicketModelService>();
var trainService = new TicketModelService(tempLogger, builder.Environment);
trainService.TrainAndSave();
builder.Services.AddSingleton(trainService);

// Register the pooled prediction engine (thread-safe for ASP.NET Core)
var modelPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");
builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(modelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

